{v:'VER',what:'the what is new card stamp is within 0.15 of the build and the three short notes still lead',
 run:function(){
   if(typeof WHATSNEW==='undefined'||typeof WHATSNEW_VER==='undefined'||typeof VER==='undefined') return 'SKIP: this build has no what is new card';
   if(parseFloat(WHATSNEW_VER)>33.62+0.001) return 'SKIP: the card has moved on, a later card check covers it';
   var bad=[], d=parseFloat(VER)-parseFloat(WHATSNEW_VER);
   if(!(d<=0.15+1e-9)) bad.push('the card is stamped v'+WHATSNEW_VER+', '+d.toFixed(2)+' behind v'+VER);
   if(WHATSNEW[0]!=='experimental switches in settings') bad.push('the card no longer leads with the short notes');
   return bad.length?bad.join('; '):null; }},
